// Клавиши хоста для стандартного джойстика БК на порте 0177714. Слева клавиша
// хоста, справа бит замкнутого контакта; что означает каждый бит, расписано в
// конфигурации машины, рядом с устройством joystick.

up:	$0001
right:	$0002
down:	$0004
left:	$0008
end:	$0010
home:	$0020
pgup:	$0040
pgdn:	$0080
